// Typ QueueAction ma znaczenie: dzialanie na kolejce; retry bez limitu obiegow. Wartości kontraktu: start, pause, resume, stop, retry, clear, enqueue, dequeue, delay, split, merge, route, branch, condition.
type QueueAction string

// Blok stałych wylicza kolejno wartości typu QueueAction w porządku przyjętym przez kontrakt komunikacji.
const (
	// Wartość QueueActionStart typu QueueAction, zapisywana w kontrakcie jako „start”, ma znaczenie: uruchom.
	QueueActionStart = "start"
	// Wartość QueueActionPause typu QueueAction, zapisywana w kontrakcie jako „pause”, ma znaczenie: wstrzymaj.
	QueueActionPause = "pause"
	// Wartość QueueActionResume typu QueueAction, zapisywana w kontrakcie jako „resume”, ma znaczenie: wznow.
	QueueActionResume = "resume"
	// Wartość QueueActionStop typu QueueAction, zapisywana w kontrakcie jako „stop”, ma znaczenie: zatrzymaj.
	QueueActionStop = "stop"
	// Wartość QueueActionRetry typu QueueAction, zapisywana w kontrakcie jako „retry”, ma znaczenie: powtorz krok; liczba obiegow nieograniczona.
	QueueActionRetry = "retry"
	// Wartość QueueActionClear typu QueueAction, zapisywana w kontrakcie jako „clear”, ma znaczenie: oproznij.
	QueueActionClear = "clear"
	// Wartość QueueActionEnqueue typu QueueAction, zapisywana w kontrakcie jako „enqueue”, ma znaczenie: dodanie zlecenia do kolejki.
	QueueActionEnqueue = "enqueue"
	// Wartość QueueActionDequeue typu QueueAction, zapisywana w kontrakcie jako „dequeue”, ma znaczenie: zdjecie zlecenia z kolejki przed wykonaniem.
	QueueActionDequeue = "dequeue"
	// Wartość QueueActionDelay typu QueueAction, zapisywana w kontrakcie jako „delay”, ma znaczenie: odlozenie wykonania zlecenia.
	QueueActionDelay = "delay"
	// Wartość QueueActionSplit typu QueueAction, zapisywana w kontrakcie jako „split”, ma znaczenie: podzial zlecenia na podzadania.
	QueueActionSplit = "split"
	// Wartość QueueActionMerge typu QueueAction, zapisywana w kontrakcie jako „merge”, ma znaczenie: scalenie kilku zlecen w jedno.
	QueueActionMerge = "merge"
	// Wartość QueueActionRoute typu QueueAction, zapisywana w kontrakcie jako „route”, ma znaczenie: skierowanie zlecenia do innej kolejki albo wykonawcy.
	QueueActionRoute = "route"
	// Wartość QueueActionBranch typu QueueAction, zapisywana w kontrakcie jako „branch”, ma znaczenie: rozgalezienie zlecenia na tory rownolegle.
	QueueActionBranch = "branch"
	// Wartość QueueActionCondition typu QueueAction, zapisywana w kontrakcie jako „condition”, ma znaczenie: warunkowe przetworzenie zlecenia.
	QueueActionCondition = "condition"
)

