// Struktura SessionConfigRuntime ma znaczenie: obszar runtime: gdzie i czym uruchamiany jest kanal. Pola struktury: ExecutionEnv, HostId, ExecutablePath, ShellPath, ConfigDirectory, StartupTimeoutMs, FactoryHarnessEnabled.
type SessionConfigRuntime struct {
	// Zasieg wykonania modelu
	ExecutionEnv *ExecutionEnv `json:"executionEnv,omitempty"`
	// Urzadzenie wykonania z rejestru urzadzen; wypelniane dla executionEnv=remote
	HostId *string `json:"hostId,omitempty"`
	// Sciezka programu kanalu; puste znaczy program z rejestru kanalow
	ExecutablePath *string `json:"executablePath,omitempty"`
	// Powloka systemowa, w ktorej uruchamiany jest program
	ShellPath *string `json:"shellPath,omitempty"`
	// Katalog konfiguracji kanalu; puste znaczy katalog konta
	ConfigDirectory *string `json:"configDirectory,omitempty"`
	// Granica czasu uruchomienia kanalu w milisekundach
	StartupTimeoutMs *int `json:"startupTimeoutMs,omitempty"`
	// Czy powloka dostawcy wnosi wlasne narzedzia i prompt fabryczny; puste znaczy tak
	FactoryHarnessEnabled *bool `json:"factoryHarnessEnabled,omitempty"`
}

// Struktura SessionConfigSessionLifecycle ma znaczenie: obszar sessionLifecycle: granice biegu sesji. Pola struktury: TurnLimit, CostBudgetUsd, WallClockLimitMs, NoProgressThreshold, StopOnNoProgress, BackgroundAllowed oraz 3 kolejnych.
type SessionConfigSessionLifecycle struct {
	// Gorna granica liczby tur modelu; zainstalowany program CLI nie zna tego pola i mowi o tym
	TurnLimit *int `json:"turnLimit,omitempty"`
	// Budzet kosztu sesji w dolarach
	CostBudgetUsd *float64 `json:"costBudgetUsd,omitempty"`
	// Granica czasu biegu sesji w milisekundach
	WallClockLimitMs *int `json:"wallClockLimitMs,omitempty"`
	// Prog obiegow bez postepu; odpowiednik pola threshold w LoopState
	NoProgressThreshold *int `json:"noProgressThreshold,omitempty"`
	// Czy przekroczenie progu ma wstrzymac bieg
	StopOnNoProgress *bool `json:"stopOnNoProgress,omitempty"`
	// Czy sesja moze trwac na rdzeniu po rozlaczeniu klienta; kontrolke zasila SessionPresence
	BackgroundAllowed *bool `json:"backgroundAllowed,omitempty"`
	// Czy kanal ma byc podnoszony po padzie procesu
	RestartOnFailure *bool `json:"restartOnFailure,omitempty"`
	// Ile razy podniesc kanal po padzie
	RestartLimit *int `json:"restartLimit,omitempty"`
	// Czy zamknac okno po zakonczeniu biegu
	AutoCloseWhenFinished *bool `json:"autoCloseWhenFinished,omitempty"`
}

// Struktura SessionConfigOrigin ma znaczenie: pochodzenie wartosci jednego obszaru konfiguracji obowiazujacej: ktory rejestr byl zrodlem prawdy oraz na ktorym poziomie zasiegu i ktorej osi wartosc zostala znaleziona.
type SessionConfigOrigin struct {
	// Obszar konfiguracji sesji
	Area SessionConfigArea `json:"area"`
	// Rejestr, z ktorego wartosc pochodzi
	Source SessionConfigSource `json:"source"`
	// Sciezka pola w obrebie obszaru; puste znaczy caly obszar
	FieldPath *string `json:"fieldPath,omitempty"`
	// Poziom zasiegu, na ktorym wartosc znaleziono
	Scope *ConfigScope `json:"scope,omitempty"`
	// Identyfikator bytu poziomu; puste dla global
	ScopeId *string `json:"scopeId,omitempty"`
	// Os rozstrzygania; puste znaczy platform
	Axis *ConfigAxis `json:"axis,omitempty"`
	// Byt osi: identyfikator modelu albo konta
	AxisId *string `json:"axisId,omitempty"`
	// Byt rejestru zrodlowego: konto, kanal, punkt dostepu albo kategoria zasad
	EntityId *string `json:"entityId,omitempty"`
}

// Struktura WorkingDirectoryResolution ma znaczenie: katalog ustawiony zestawiony z katalogiem faktycznie uzywanym wraz z powodem rozejscia.
type WorkingDirectoryResolution struct {
	// Katalog faktycznie uzywany
	EffectivePath string `json:"effectivePath"`
	// Czy katalog uzywany rozni sie od ustawionego
	Degraded bool `json:"degraded"`
	// Powod rozejscia; none, gdy katalog ustawiony jest uzywany
	Reason WorkingDirectoryDegradation `json:"reason"`
	// Katalog ustawiony; puste, gdy Operator go nie wskazal
	RequestedPath *string `json:"requestedPath,omitempty"`
	// Opis rozejscia dla Operatora
	Detail *string `json:"detail,omitempty"`
	// Czas sprawdzenia w milisekundach epoki
	CheckedAt int64 `json:"checkedAt"`
}

// Struktura SessionConfigFieldCapability ma znaczenie: deklaracja zdolnosci adaptera dla jednego pola modelu konfiguracji sesji.
type SessionConfigFieldCapability struct {
	// Obszar konfiguracji sesji
	Area SessionConfigArea `json:"area"`
	// Sciezka pola w modelu konfiguracji,na przykład sessionLifecycle.turnLimit.
	FieldPath string `json:"fieldPath"`
	// Stopien obslugi pola
	Support CapabilitySupport `json:"support"`
	// Powierzchnia, na ktora adapter tlumaczy pole
	Surface AdapterSurface `json:"surface"`
	// Postac, w jakiej pole trafia na powierzchnie; opis diagnostyczny, nie nazwa do budowania interfejsu
	Mapping *string `json:"mapping,omitempty"`
	// Powod ograniczenia; wypelniany dla partial oraz unsupported
	Reason *string `json:"reason,omitempty"`
}

// Struktura SessionConfigAreaCapability ma znaczenie: deklaracja zdolnosci adaptera dla calego obszaru konfiguracji sesji; skrot dla okna konfiguracji, zeby nie liczylo pol samodzielnie.
type SessionConfigAreaCapability struct {
	// Obszar konfiguracji sesji
	Area SessionConfigArea `json:"area"`
	// Stopien obslugi obszaru
	Support CapabilitySupport `json:"support"`
	// Liczba pol obszaru bez odpowiednika u dostawcy
	UnsupportedFieldCount int `json:"unsupportedFieldCount"`
	// Powod ograniczenia obszaru
	Reason *string `json:"reason,omitempty"`
}

// Struktura AdapterCapabilities ma znaczenie: komplet deklaracji zdolnosci jednego adaptera dostawcy. Pola struktury: AdapterId, Transport, ProbedAt, Areas, Fields, ChannelId, AccountId, ProviderVersion, Reason.
type AdapterCapabilities struct {
	// Adapter, ktorego dotyczy deklaracja
	AdapterId string `json:"adapterId"`
	// Transport obslugiwany przez adapter
	Transport ProviderTransport `json:"transport"`
	// Czas sprawdzenia zdolnosci w milisekundach epoki
	ProbedAt int64 `json:"probedAt"`
	// Deklaracja dla kazdego obszaru konfiguracji sesji
	Areas []SessionConfigAreaCapability `json:"areas"`
	// Deklaracja dla kazdego pola konfiguracji sesji
	Fields []SessionConfigFieldCapability `json:"fields"`
	// Kanal modelu, dla ktorego zdolnosci sprawdzono
	ChannelId *string `json:"channelId,omitempty"`
	// Konto, dla ktorego zdolnosci sprawdzono
	AccountId *string `json:"accountId,omitempty"`
	// Wersja programu albo interfejsu dostawcy; puste, gdy wersji nie dalo sie ustalic
	ProviderVersion *string `json:"providerVersion,omitempty"`
	// Powod, dla ktorego deklaracja jest niepelna albo pusta; puste, gdy adapter zglosil komplet zdolnosci
	Reason *string `json:"reason,omitempty"`
}

// Struktura SessionConfigEffective ma znaczenie: konfiguracja sesji obowiazujaca po rozstrzygnieciu osmiu poziomow zasiegu i trzech osi (platform, model, account) wraz ze wskazaniem pochodzenia kazdego obszaru, rozejsciem katalogu roboczego i wykazem.
type SessionConfigEffective struct {
	// Konfiguracja po rozstrzygnieciu
	Config SessionConfig `json:"config"`
	// Pochodzenie kazdego obszaru
	Origins []SessionConfigOrigin `json:"origins"`
	// Katalog ustawiony zestawiony z faktycznie uzywanym
	WorkingDirectory WorkingDirectoryResolution `json:"workingDirectory"`
	// Czas rozstrzygniecia w milisekundach epoki
	ResolvedAt int64 `json:"resolvedAt"`
	// Pola wypelnione, ktorych adapter dostawcy nie obsluzy; wypelnienie takiego pola niczego nie
	UnsupportedFields []SessionConfigFieldCapability `json:"unsupportedFields,omitempty"`
	// Pelna deklaracja zdolnosci adaptera; wypelniana na zadanie
	Capabilities *AdapterCapabilities `json:"capabilities,omitempty"`
}

